"""Actual integrated release catalogue over HTTP, never a proposal-only mock."""
import csv,io,json,os,shutil,threading
from pathlib import Path
from functools import partial
from http.server import ThreadingHTTPServer,SimpleHTTPRequestHandler
from playwright.sync_api import sync_playwright,expect
ROOT=Path(os.environ.get('MOTIONX_RC_ROOT',Path(__file__).resolve().parents[1]))
class Quiet(SimpleHTTPRequestHandler):
 def log_message(self,*_):pass

def main():
 report=json.loads((ROOT/'data/release-candidate/reports/release-audit.json').read_text());expected={r['id']:r for r in report['integrated_records']};server=ThreadingHTTPServer(('127.0.0.1',0),partial(Quiet,directory=str(ROOT.parent)));threading.Thread(target=server.serve_forever,daemon=True).start();url=f'http://127.0.0.1:{server.server_port}/{ROOT.name}/';checks=0
 def passed(label):
  nonlocal checks;checks+=1;print('PASS '+label,flush=True)
 try:
  with sync_playwright() as pw:
   browser=pw.chromium.launch(executable_path=os.environ.get('CHROMIUM') or shutil.which('chromium'),headless=True,args=['--no-sandbox']);page=browser.new_page(viewport={'width':1440,'height':1000},accept_downloads=True);errors=[];page.on('pageerror',lambda e:errors.append(str(e)));page.goto(url,wait_until='domcontentloaded');expect(page.locator('#count')).to_have_text('42474 records',timeout=45000)
   rows=page.evaluate('async()=>{const b=await catalog.exportBundle(catalog.rows.filter(r=>r.id.startsWith("globalcompany-")));return b.rows;}');assert len(rows)==182;assert {r['id'] for r in rows}==set(expected);assert all(r['lat'] is None and not r['capabilities'] and not r['research_review']['human_approved'] for r in rows)
   passed('all 182 new directory entries load through real index, hash-bound lazy shard and export pipeline; total 42478 storage/42474 normal')
   page.locator('#advancedFilters').evaluate('(d)=>d.open=true');page.locator('#category').select_option('Animation');page.locator('#search').fill('a_BAHN');expect(page.locator('#count')).to_have_text('1 record');page.locator('#list a.profile-link').click();expect(page.locator('#profileTitle')).to_have_text('a_BAHN');expect(page.locator('#detailContent')).to_contain_text('Original source labels:');expect(page.locator('#detailContent')).to_contain_text('Animation production');expect(page.locator('#detailContent')).to_contain_text('No facility capability is confirmed');expect(page.locator('#detailContent a[href="data/release-candidate/reports/dashboard.html"]')).to_be_visible();page.locator('#close').click()
   with page.expect_download() as download:page.locator('#exportCsv').click()
   csv_rows=list(csv.DictReader(io.StringIO(Path(download.value.path()).read_text(encoding='utf-8-sig'))));assert len(csv_rows)==1 and csv_rows[0]['name']=='a_BAHN';assert 'Animation production' in json.loads(csv_rows[0]['source_category']);assert csv_rows[0]['license']=='UNSPECIFIED' and not csv_rows[0]['lat'] and not csv_rows[0]['capabilities'];assert 'source-wide' in csv_rows[0]['attribution'] or 'Source-wide' in csv_rows[0]['attribution']
   passed('normalised Animation filter, provisional profile, original source labels, scoped attribution and filtered CSV work for a newly integrated company')
   page.locator('#resetFilters').click();page.locator('#advancedFilters').evaluate('(d)=>d.open=true');page.locator('#category').select_option('Game Development');page.locator('#commercialRole').select_option('client');page.locator('#search').fill('2Up Games');expect(page.locator('#count')).to_have_text('1 record');page.locator('#confirmedOnly').check();expect(page.locator('#count')).to_have_text('0 records');page.locator('#resetFilters').click();page.locator('#scopeMode').select_option('excluded');expect(page.locator('#count')).to_have_text('4 records');expect(page.locator('#list')).to_contain_text('The Inside Track');page.locator('#resetFilters').click();page.locator('#search').fill('Envy Studios');expect(page.locator('#count')).to_have_text('1 record')
   passed('game-company client eligibility needs no capture, confirmed-only excludes new unverified claims, and four audio-only exclusions retain multidisciplinary Envy')
   page.locator('#resetFilters').click();page.locator('#search').fill('ModelFarm');page.locator('#city').fill('Brisbane');expect(page.locator('#count')).to_have_text('1 record');page.locator('#fitResults').click();page.wait_for_function('companyReferenceLayer.getLayers().length===2');expect(page.locator('#unmappedCount')).to_contain_text('1 matching directory records have no original map coordinates; 2 separate approximate company reference points');mid='boutique-bd922ba2cd1dcd66361049c27ed0';assert page.evaluate('(id)=>catalog.rows.find(r=>r.id===id).lat===null',mid)
   with page.expect_download() as download:page.locator('#exportCsv').click()
   model=list(csv.DictReader(io.StringIO(Path(download.value.path()).read_text(encoding='utf-8-sig'))));assert len(model)==1 and not model[0]['lat'];assert json.loads(model[0]['company_reference_location'])['city']=='Adelaide';assert json.loads(model[0]['additional_company_reference_locations'])[0]['city']=='Brisbane'
   page.locator('#list a.profile-link').click();expect(page.locator('#detailContent')).to_contain_text('Additional source-supported city references');expect(page.locator('#detailContent')).to_contain_text('Brisbane');page.locator('#close').click()
   passed('ModelFarm Adelaide/Brisbane references are separately selectable map points for one unchanged company identity, with accurate city search and CSV')
   page.locator('#resetFilters').click();page.locator('#country').select_option('Singapore');page.locator('#recordKind').select_option('company_reference');page.locator('#geographicView').select_option('company_city');expect(page.locator('#count')).to_have_text('2 records');page.locator('#fitResults').click();expect(page.locator('.company-city-reference')).to_have_count(1);marker=page.locator('.company-city-reference');marker.focus();marker.press('Space');page.evaluate('map.panBy([0,30],{animate:false})');expect(page.locator('.leaflet-popup-content')).to_contain_text('Scrawl Animation');expect(page.locator('.leaflet-popup-content')).to_contain_text('Robot Playground Media');page.locator('.leaflet-popup-content [data-record-id="boutique-02b32b3e25b0693f01f05a67e5f2"]').press('Enter');expect(page.locator('#profileTitle')).to_have_text('Scrawl Animation');page.locator('#close').click()
   passed('two new Singapore city references retain identical coordinates and an accessible chooser across viewport movement')
   for name in ['SIUNG FILM PRODUCTIONS SDN.BHD','VENTURA INTERACTIVE']:
    page.locator('#resetFilters').click();page.locator('#search').fill(name);page.wait_for_function('!matches.some(r=>r.id.startsWith("globalcompany-"))')
   target=next(r for r in expected.values() if r['name']=='Mighty Eyes');page.goto(url+'#/location/'+target['id']);expect(page.locator('#profileTitle')).to_have_text('Mighty Eyes',timeout=45000);page.set_viewport_size({'width':390,'height':844});expect(page.locator('#detailContent')).to_contain_text('current operation');assert page.evaluate('document.documentElement.scrollWidth<=innerWidth');page.locator('#close').click();page.locator('#listTab').click();page.locator('#resetFilters').click();page.locator('#search').fill('Mighty Eyes');expect(page.locator('#count')).to_have_text('1 record');page.locator('#list a.profile-link').focus();page.locator('#list a.profile-link').press('Enter');expect(page.locator('#profileTitle')).to_have_text('Mighty Eyes');assert not errors,errors
   passed('withheld companies do not leak into new intake; shareable provisional links, 390px mobile layout and keyboard profile navigation work')
   page.goto(url+'data/release-candidate/reports/dashboard.html');expect(page.locator('[data-company]')).to_have_count(184);expect(page.locator('a',has_text='Open integrated provisional profile')).to_have_count(182);page.locator('#reviewState').select_option('withhold_industry_scope');expect(page.locator('#reviewCount')).to_contain_text('2 of 184');expect(page.locator('article:visible')).to_have_count(2);page.locator('#reviewState').select_option('admit_minimal_factual_reference');page.locator('#reviewSearch').fill('2Up Games');expect(page.locator('#reviewCount')).to_contain_text('1 of 184');page.locator('article:visible details summary').click();expect(page.locator('article:visible pre')).to_contain_text('UNSPECIFIED');expect(page.locator('article:visible pre')).to_contain_text('false');assert page.evaluate('document.documentElement.scrollWidth<=innerWidth');assert not errors,errors;browser.close()
   passed('packaged 390px admission dashboard filters all 184 decisions, exposes exact fields/rights/false approval and links only the 182 actual directory records')
 finally:server.shutdown();server.server_close()
 Path('/tmp/motionx-rc-browser.json').write_text(json.dumps({'checks':checks,'integrated_new_companies':182,'actual_directory_records':42478,'conditions':'Actual local HTTP subdirectory and installed Chromium; desktop 1440x1000/mobile 390x844; not deployed Pages or independent company verification.'},indent=2)+'\n');print(str(checks)+' release-candidate HTTP checks passed',flush=True)
if __name__=='__main__':main()
